using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using Memories.Gameplay.Memories;using Memories.Gameplay.Reactions;
[InitializeOnLoad]public static class DockGraphFinalize{static DockGraphFinalize(){EditorApplication.delayCall+=Run;}static void Run(){if(File.Exists("Temp/DockGraphFinalize.txt"))return;try{var g=AssetDatabase.LoadAssetAtPath<MemoryGraph>("Assets/_Project/Configs/Memories/Park/ParkBoatMemory.asset");if(!g)return;foreach(var n in g.nodes.OfType<MemoryStartNode>().Where(n=>!n.GetOutputPort("next").IsConnected).ToArray()){g.RemoveNode(n);UnityEngine.Object.DestroyImmediate(n,true);}EditorUtility.SetDirty(g);AssetDatabase.SaveAssetIfDirty(g);string report="";if(!g.TryGetSequence(out var frames,out var error))throw new Exception(error);report+="Memory frames="+frames.Count+" valid\n";foreach(string name in new[]{"Dock_Lily","Dock_Boat","Cafe_Finish","Cafe_Coffee","Cafe_Napkin","Cafe_BuyOrder"}){var r=AssetDatabase.LoadAssetAtPath<ReactionGraph>("Assets/_Project/Configs/Reactions/Park/"+name+".asset");if(!r.TryGetSequence(out _,out error))throw new Exception(name+": "+error);report+=name+" valid\n";}var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Temp/DockGraphFinalize.txt",report);}catch(Exception e){File.WriteAllText("Temp/DockGraphFinalize.txt",e.ToString());}}}